File:
plugins {
    id 'java'
    id 'application'
}

group = 'com.example'
version = '1.0.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // Excel (XLS/XLSX)
    implementation 'org.apache.poi:poi:5.3.0'
    implementation 'org.apache.poi:poi-ooxml:5.3.0'

    // CSV
    implementation 'com.opencsv:opencsv:5.9'

    // PDF
    implementation 'com.github.librepdf:openpdf:2.0.3'

    // Logging (optional, aber oft hilfreich)
    implementation 'org.slf4j:slf4j-simple:2.0.13'

    // Tests
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.3'
}

tasks.test {
    useJUnitPlatform()
}

application {
    // Falls du später eine Main-Klasse hast, hier eintragen:
    // mainClass = 'com.example.Main'
}

plugins {
    id("java")
    id("org.springframework.boot") version "3.3.2"
    id("io.spring.dependency-management") version "1.1.6"
}

group = "de.example"
version = "1.0.0"

java {
    toolchain {
        languageVersion.set(JavaLanguageVersion.of(21))
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // Spring WebFlux enthält WebClient
    implementation("org.springframework.boot:spring-boot-starter-webflux")

    // Für Retry/Resilience, Circuit Breaker etc.
    implementation("io.github.resilience4j:resilience4j-reactor:2.2.0")
    implementation("io.github.resilience4j:resilience4j-retry:2.2.0")
    implementation("io.github.resilience4j:resilience4j-timelimiter:2.2.0")

    // Logging
    implementation("org.slf4j:slf4j-api")

    // Optional: falls du Konfiguration per Properties willst
    annotationProcessor("org.springframework.boot:spring-boot-configuration-processor")

    // Tests
    testImplementation("org.springframework.boot:spring-boot-starter-test")
    testImplementation("io.projectreactor:reactor-test")
    testImplementation("org.mockito:mockito-core")
}

tasks.withType<Test> {
    useJUnitPlatform()
}

tasks.withType<JavaCompile> {
    options.encoding = "UTF-8"
    options.release.set(21)
}

plugins {
    id 'java'
    id 'application'
}

group = 'de.example.batch'
version = '1.0.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // CSV-Parsing
    implementation 'org.apache.commons:commons-csv:1.11.0'

    // Excel-Erzeugung
    implementation 'org.apache.poi:poi:5.3.0'
    implementation 'org.apache.poi:poi-ooxml:5.3.0'

    // PDF-Erzeugung
    implementation 'com.itextpdf:itext7-core:8.0.5'

    // Logging
    implementation 'org.slf4j:slf4j-api:2.0.13'
    runtimeOnly 'org.slf4j:slf4j-simple:2.0.13'

    // Optional: bessere CLI-Argumente / Konfiguration
    implementation 'info.picocli:picocli:4.7.6'
    annotationProcessor 'info.picocli:picocli-codegen:4.7.6'

    // Tests
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.3'
}

application {
    // anpassen an deine Main-Klasse
    mainClass = 'de.example.batch.Main'
}

tasks.test {
    useJUnitPlatform()
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
    options.compilerArgs += ['-parameters']
}

jar {
    manifest {
        attributes(
                'Main-Class': application.mainClass.get()
        )
    }
}

plugins {
    id 'java'
    id 'application'
}

group = 'com.example'
version = '1.0.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // JSON parsing
    implementation 'com.fasterxml.jackson.core:jackson-databind:2.17.2'
    implementation 'com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.17.2' // optional, falls du später YAML willst

    // XML parsing / validation
    implementation 'org.apache.commons:commons-configuration2:2.10.1'
    implementation 'org.glassfish.jaxb:jaxb-runtime:4.0.5'

    // Optional: XML Schema Validation / DOM / SAX helpers
    implementation 'xerces:xercesImpl:2.12.2'

    // Logging
    implementation 'org.slf4j:slf4j-api:2.0.16'
    runtimeOnly 'ch.qos.logback:logback-classic:1.5.8'

    // Testing
    testImplementation 'org.junit.jupiter:junit-jupiter:5.11.0'
    testImplementation 'org.assertj:assertj-core:3.26.3'
}

tasks.test {
    useJUnitPlatform()
}

application {
    // anpassen an deine Main-Klasse
    mainClass = 'com.example.Main'
}

plugins {
    id 'java'
    id 'org.springframework.boot' version '3.3.2'
    id 'io.spring.dependency-management' version '1.1.6'
}

group = 'com.example'
version = '0.0.1-SNAPSHOT'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

ext {
    resilience4jVersion = '2.2.0'
}

dependencies {
    // Spring Boot WebFlux für WebClient (asynchrone HTTP-Calls, gute Timeout-Kontrolle)
    implementation 'org.springframework.boot:spring-boot-starter-webflux'

    // JSON-Verarbeitung via Jackson
    implementation 'com.fasterxml.jackson.core:jackson-databind'
    implementation 'com.fasterxml.jackson.module:jackson-module-kotlin'

    // Resilience4j für Retry, Circuit Breaker, TimeLimiter etc.
    implementation "io.github.resilience4j:resilience4j-spring-boot3:${resilience4jVersion}"
    implementation "io.github.resilience4j:resilience4j-retry:${resilience4jVersion}"
    implementation "io.github.resilience4j:resilience4j-timelimiter:${resilience4jVersion}"
    implementation "io.github.resilience4j:resilience4j-circuitbreaker:${resilience4jVersion}"

    // Optional: Logging
    implementation 'org.springframework.boot:spring-boot-starter-logging'

    // Tests
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testImplementation 'io.projectreactor:reactor-test'
}

tasks.named('test') {
    useJUnitPlatform()
}

